'use client';

import { useState } from 'react';
import { X, TrendingUp, TrendingDown } from 'lucide-react';
import { addTransaction } from '../actions/transactions';

interface TransactionModalProps {
  isOpen: boolean;
  onClose: () => void;
  defaultType?: 'ingreso' | 'gasto';
}

export default function TransactionModal({ isOpen, onClose, defaultType = 'gasto' }: TransactionModalProps) {
  const [type, setType] = useState<'ingreso' | 'gasto'>(defaultType);
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setLoading(true);

    const formData = new FormData(event.currentTarget);
    formData.append('type', type);

    try {
      await addTransaction(formData);
      onClose();
    } catch (error) {
      console.error(error);
      alert('Hubo un error al guardar');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-xs z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl max-w-md w-full p-6 shadow-2xl space-y-6">
        <div className="flex justify-between items-center">
          <h3 className="font-bold text-lg text-slate-900">Nueva Transacción</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 cursor-pointer">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="grid grid-cols-2 gap-2 bg-slate-100 p-1 rounded-xl">
          <button
            type="button"
            onClick={() => setType('ingreso')}
            className={`py-2 rounded-lg text-xs font-semibold flex items-center justify-center space-x-1.5 transition-all cursor-pointer ${
              type === 'ingreso' ? 'bg-emerald-600 text-white shadow-xs' : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            <TrendingUp className="w-4 h-4" />
            <span>Ingreso</span>
          </button>
          <button
            type="button"
            onClick={() => setType('gasto')}
            className={`py-2 rounded-lg text-xs font-semibold flex items-center justify-center space-x-1.5 transition-all cursor-pointer ${
              type === 'gasto' ? 'bg-rose-600 text-white shadow-xs' : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            <TrendingDown className="w-4 h-4" />
            <span>Gasto</span>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-600 mb-1">Concepto o Descripción</label>
            <input 
              name="concept" 
              required
              placeholder="Ej. Supermercado, Sueldo..." 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3.5 py-2.5 text-sm text-slate-800 focus:outline-indigo-600"
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-600 mb-1">Monto ($)</label>
            <input 
              name="amount" 
              type="number"
              step="0.01"
              required
              placeholder="0.00" 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3.5 py-2.5 text-sm text-slate-800 focus:outline-indigo-600"
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-600 mb-1">Categoría</label>
            <select 
              name="category"
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3.5 py-2.5 text-sm text-slate-800 focus:outline-indigo-600"
            >
              <option value="Comida">Comida / Supermercado</option>
              <option value="Servicios">Servicios</option>
              <option value="Ocio">Ocio y Salidas</option>
              <option value="Trabajo">Trabajo / Ingresos</option>
              <option value="Varios">Varios</option>
            </select>
          </div>

          <button 
            type="submit"
            disabled={loading}
            className="w-full bg-indigo-600 text-white py-3 rounded-xl font-medium text-sm hover:bg-indigo-700 transition-colors cursor-pointer disabled:opacity-50"
          >
            {loading ? 'Guardando...' : 'Registrar Movimiento'}
          </button>
        </form>
      </div>
    </div>
  );
}