'use client';

import { Wallet, QrCode, Home, PieChart, Users, Settings } from 'lucide-react';

interface NavbarProps {
  onOpenQR: () => void;
}

export default function Navbar({ onOpenQR }: NavbarProps) {
  return (
    <>
      {/* HEADER SUPERIOR */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-xs">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-sm">
              <Wallet className="w-6 h-6" />
            </div>
            <div>
              <h1 className="font-bold text-lg text-slate-900 leading-tight">Voluntariado Finanzas</h1>
              <p className="text-xs text-slate-500">Hola, Delia 👋</p>
            </div>
          </div>
          <button 
            onClick={onOpenQR}
            className="flex items-center space-x-1.5 bg-indigo-50 text-indigo-600 px-3.5 py-2 rounded-xl text-sm font-medium hover:bg-indigo-100 transition-colors shadow-xs cursor-pointer"
          >
            <QrCode className="w-4 h-4" />
            <span className="hidden sm:inline">Vincular Pareja</span>
          </button>
        </div>
      </header>

      {/* NAVEGACIÓN INFERIOR (MÓVIL) */}
      <nav className="sm:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 px-6 py-3 flex justify-around items-center z-30 shadow-lg">
        <button className="flex flex-col items-center text-indigo-600 transition-colors cursor-pointer">
          <Home className="w-5 h-5" />
          <span className="text-[10px] mt-1 font-medium">Inicio</span>
        </button>
        <button className="flex flex-col items-center text-slate-400 hover:text-slate-600 transition-colors cursor-pointer">
          <PieChart className="w-5 h-5" />
          <span className="text-[10px] mt-1">Gastos</span>
        </button>
        <button onClick={onOpenQR} className="flex flex-col items-center text-slate-400 hover:text-slate-600 transition-colors cursor-pointer">
          <Users className="w-5 h-5" />
          <span className="text-[10px] mt-1">Pareja</span>
        </button>
        <button className="flex flex-col items-center text-slate-400 hover:text-slate-600 transition-colors cursor-pointer">
          <Settings className="w-5 h-5" />
          <span className="text-[10px] mt-1">Ajustes</span>
        </button>
      </nav>
    </>
  );
}