'use client';

import { useState } from 'react';
import { PlusCircle } from 'lucide-react';
import Navbar from '../components/Navbar';
import TransactionModal from '../components/TransactionModal';

export default function DashboardPage() {
  const [showTxModal, setShowTxModal] = useState(false);
  const [txType, setTxType] = useState<'ingreso' | 'gasto'>('gasto');

  const balanceTotal = 1250.00;
  const ingresosMes = 2400.00;
  const gastosMes = 1150.00;

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 pb-24 md:pb-10">
      <Navbar onOpenQR={() => alert('Modal QR')} />

      <main className="max-w-4xl mx-auto px-4 py-6 space-y-6">
        <section className="bg-gradient-to-br from-indigo-600 to-violet-700 rounded-2xl p-6 text-white shadow-lg">
          <p className="text-indigo-100 text-sm font-medium">Balance Total del Mes</p>
          <h2 className="text-3xl sm:text-4xl font-extrabold mt-1">
            ${balanceTotal.toLocaleString('es-ES', { minimumFractionDigits: 2 })}
          </h2>
        </section>

        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => { setTxType('ingreso'); setShowTxModal(true); }}
            className="bg-white border border-slate-200 p-4 rounded-xl flex items-center justify-center space-x-2 font-medium text-slate-700 hover:bg-slate-50 transition-all shadow-xs cursor-pointer"
          >
            <PlusCircle className="w-5 h-5 text-emerald-600" />
            <span>Nuevo Ingreso</span>
          </button>
          <button 
            onClick={() => { setTxType('gasto'); setShowTxModal(true); }}
            className="bg-white border border-slate-200 p-4 rounded-xl flex items-center justify-center space-x-2 font-medium text-slate-700 hover:bg-slate-50 transition-all shadow-xs cursor-pointer"
          >
            <PlusCircle className="w-5 h-5 text-rose-600" />
            <span>Nuevo Gasto</span>
          </button>
        </div>
      </main>

      <TransactionModal 
        isOpen={showTxModal} 
        onClose={() => setShowTxModal(false)} 
        defaultType={txType} 
      />
    </div>
  );
}